CREATE TABLE t0(id INTEGER PRIMARY KEY, c0 TEXT CHECK(c0 IS NULL OR length(c0) < 40), c1 INT, c2 VARCHAR(10), c3  COLLATE NOCASE, c4  COLLATE NOCASE);
INSERT OR IGNORE INTO t0(c0, c1, c2, c3, c4) VALUES(4, 1, 'omega', x'979fde', 3);
CREATE TABLE t1(id INTEGER PRIMARY KEY, c0 BLOB, c1 VARCHAR(10) CHECK(c1 IS NULL OR length(c1) < 40), c2 NUMERIC CHECK(c2 IS NULL OR length(c2) < 40), c3 INTEGER COLLATE NOCASE, c4);
INSERT OR IGNORE INTO t1(c0, c1, c2, c3, c4) VALUES(2, 105.37, -2.5, 'it''s', NULL);
INSERT OR IGNORE INTO t1(c0, c1, c2, c3, c4) VALUES(363.19, 'Lambda', 355, ' pad ', x'981aa2');
INSERT OR IGNORE INTO t1(c0, c1, c2, c3, c4) VALUES(NULL, 123456789012, -154, -483, -231.9);
SELECT length('xi'), upper('xi'), lower('xi'), substr('xi', 2, 5), instr('xi', 'señor'), replace('xi', '', ''), trim('xi'), ltrim('xi', 'ab'), hex('xi'), quote('xi'), unicode('xi'), 'xi' LIKE '%a_', 'xi' GLOB '?', char(85, 287), 'xi' || 'señor', 'xi' < 'señor', 'xi' = 'señor' COLLATE NOCASE;
SELECT length('0x1F'), upper('0x1F'), lower('0x1F'), substr('0x1F', -3, 0), instr('0x1F', 'MU'), replace('0x1F', 'é', 'XY'), trim('0x1F'), ltrim('0x1F', 'ab'), hex('0x1F'), quote('0x1F'), unicode('0x1F'), '0x1F' LIKE '%', '0x1F' GLOB 'a*', char(89, 831), '0x1F' || 'MU', '0x1F' < 'MU', '0x1F' = 'MU' COLLATE NOCASE;
SELECT length('42'), upper('42'), lower('42'), substr('42', 2, 1), instr('42', 'señor'), replace('42', 'a', 'XY'), trim('42'), ltrim('42', 'ab'), hex('42'), quote('42'), unicode('42'), '42' LIKE '%é%', '42' GLOB 'a*', char(74, 233), '42' || 'señor', '42' < 'señor', '42' = 'señor' COLLATE NOCASE;
SELECT length('Lambda'), upper('Lambda'), lower('Lambda'), substr('Lambda', 2, 2), instr('Lambda', 'rho'), replace('Lambda', 'e', 'XY'), trim('Lambda'), ltrim('Lambda', 'ab'), hex('Lambda'), quote('Lambda'), unicode('Lambda'), 'Lambda' LIKE 'A%', 'Lambda' GLOB '?', char(68, 992), 'Lambda' || 'rho', 'Lambda' < 'rho', 'Lambda' = 'rho' COLLATE NOCASE;
SELECT length('iota'), upper('iota'), lower('iota'), substr('iota', 0, 1), instr('iota', 'delta'), replace('iota', 'e', 'XY'), trim('iota'), ltrim('iota', 'ab'), hex('iota'), quote('iota'), unicode('iota'), 'iota' LIKE '_', 'iota' GLOB '?', char(66, 999), 'iota' || 'delta', 'iota' < 'delta', 'iota' = 'delta' COLLATE NOCASE;
SELECT length('-7'), upper('-7'), lower('-7'), substr('-7', -2, 4), instr('-7', 'delta'), replace('-7', '', ''), trim('-7'), ltrim('-7', 'ab'), hex('-7'), quote('-7'), unicode('-7'), '-7' LIKE '%é%', '-7' GLOB '*[a-m]*', char(90, 527), '-7' || 'delta', '-7' < 'delta', '-7' = 'delta' COLLATE NOCASE;
CREATE UNIQUE INDEX IF NOT EXISTS i77 ON t0(c3 DESC, id);
SELECT id, c3 FROM t0 WHERE c3 IS NOT -1 ORDER BY c3, id;
SELECT count(*) FROM t0 INDEXED BY i77 WHERE c3 IS NOT NULL;
REINDEX t0;
DROP INDEX IF EXISTS i77;
